UPDATE decision_nodes SET data = '{"type":"result","module":5,"title":"Large-Volume Paracentesis","body":"For therapeutic drainage, reassess symptoms, vitals, and leak/bleeding during removal.\n\nGive [Albumin](#/drug/albumin/large-volume-paracentesis) **6-8 g per liter of ascites removed** (20% or 25% solution) when **>5 L** is removed (AASLD 2021, Class IIa). For smaller taps, consider albumin when AKI risk or acute-on-chronic liver failure is present. Example: 8 L removed → 48-64 g albumin IV. Prevents post-paracentesis circulatory dysfunction.","citation":[1,2],"recommendation":"Albumin reduces post-paracentesis circulatory dysfunction after large-volume drainage.","confidence":"recommended","summary":"Large-volume drainage needs monitoring and albumin replacement planning."}'::jsonb
WHERE id = 'para-albumin' AND tree_id = 'paracentesis';

